import React, { createContext, Component } from 'react';
import PropTypes from 'prop-types';
import api from '../services/api';

/* ===================================================================
   AuthContext — Likhesh | 24BCE0463
   Role-based auth for Student, Peon, and Admin.
   Integrates with MySQL backend API, with localStorage fallback.
   =================================================================== */

export const AuthContext = createContext();

const DEFAULT_USERS_LIKHESH_24BCE0463 = [
  { username: 'student', password: 'student123', role: 'student', name: 'Student User', createdAt: '2026-10-20' },
  { username: 'peon', password: 'peon123', role: 'peon', name: 'Gate Peon', createdAt: '2026-10-20' },
  { username: 'admin', password: 'admin123', role: 'admin', name: 'System Administrator', createdAt: '2026-10-20' },
  { username: 'likhesh', password: '24BCE0463', role: 'admin', name: 'Likhesh (Super Admin)', createdAt: '2026-10-20' },
];

class Likhesh24BCE0463AuthProvider extends Component {
  constructor(props) {
    super(props);
    const likheshSession_24BCE0463 = JSON.parse(
      localStorage.getItem('likhesh_auth_24BCE0463') || 'null'
    );

    const rawUsers = localStorage.getItem('likhesh_users_list_24BCE0463');
    const likheshUsers_24BCE0463 = rawUsers ? JSON.parse(rawUsers) : DEFAULT_USERS_LIKHESH_24BCE0463;
    if (!rawUsers) {
      localStorage.setItem('likhesh_users_list_24BCE0463', JSON.stringify(DEFAULT_USERS_LIKHESH_24BCE0463));
    }

    this.state = {
      likheshUser_24BCE0463: likheshSession_24BCE0463,
      likheshUsers_24BCE0463: likheshUsers_24BCE0463,
      likheshBackendOnline_24BCE0463: false,
    };
    console.log('[Likhesh | 24BCE0463] AuthProvider initialized, user:', likheshSession_24BCE0463?.name || 'none');
  }

  componentDidMount() {
    this.checkBackendHealthLikhesh24BCE0463();
  }

  persistUsersLikhesh24BCE0463 = (users) => {
    localStorage.setItem('likhesh_users_list_24BCE0463', JSON.stringify(users));
  };

  checkBackendHealthLikhesh24BCE0463 = async () => {
    const isOnline = await api.checkHealth();
    this.setState({ likheshBackendOnline_24BCE0463: isOnline });
    console.log('[Likhesh | 24BCE0463] Backend status:', isOnline ? 'ONLINE (MySQL)' : 'OFFLINE (Local)');
  };

  loginLikhesh24BCE0463 = async (username, password) => {
    const cleanUser = username.toLowerCase().trim();

    // 1. First try API login to MySQL backend
    try {
      const apiRes = await api.login(cleanUser, password);
      if (apiRes && apiRes.success && apiRes.data) {
        const { token, user } = apiRes.data;
        const likheshSession_24BCE0463 = {
          username: user.username,
          role: user.role,
          name: user.name,
          id: user.id,
        };

        if (token) {
          localStorage.setItem('likhesh_token_24BCE0463', token);
        }
        localStorage.setItem('likhesh_auth_24BCE0463', JSON.stringify(likheshSession_24BCE0463));

        this.setState({
          likheshUser_24BCE0463: likheshSession_24BCE0463,
          likheshBackendOnline_24BCE0463: true,
        });

        console.log('[Likhesh | 24BCE0463] MySQL login success for:', user.name);
        return { success: true };
      }
    } catch (e) {
      console.warn('[Likhesh | 24BCE0463] API login error, falling back to local:', e.message);
    }

    // 2. Fallback to active users list
    const likheshFound_24BCE0463 = this.state.likheshUsers_24BCE0463.find(
      (u) => u.username.toLowerCase() === cleanUser && u.password === password
    );

    if (likheshFound_24BCE0463) {
      const likheshSession_24BCE0463 = {
        username: likheshFound_24BCE0463.username,
        role: likheshFound_24BCE0463.role,
        name: likheshFound_24BCE0463.name,
      };
      localStorage.setItem('likhesh_auth_24BCE0463', JSON.stringify(likheshSession_24BCE0463));
      this.setState({ likheshUser_24BCE0463: likheshSession_24BCE0463 });
      console.log('[Likhesh | 24BCE0463] Local login success for:', likheshSession_24BCE0463.name);
      return { success: true };
    }

    console.log('[Likhesh | 24BCE0463] Login failed for:', username);
    return { success: false, message: 'Invalid username or password.' };
  };

  logoutLikhesh24BCE0463 = () => {
    localStorage.removeItem('likhesh_auth_24BCE0463');
    localStorage.removeItem('likhesh_token_24BCE0463');
    this.setState({ likheshUser_24BCE0463: null });
    console.log('[Likhesh | 24BCE0463] Logged out');
  };

  // Admin User Management Methods — Likhesh 24BCE0463
  addUserLikhesh24BCE0463 = (newUser) => {
    const cleanUser = newUser.username.toLowerCase().trim();
    if (this.state.likheshUsers_24BCE0463.some((u) => u.username.toLowerCase() === cleanUser)) {
      return { success: false, message: 'Username already exists.' };
    }

    const createdUser = {
      username: cleanUser,
      password: newUser.password,
      role: newUser.role || 'student',
      name: newUser.name || newUser.username,
      createdAt: new Date().toISOString().split('T')[0],
    };

    this.setState((prev) => {
      const updated = [...prev.likheshUsers_24BCE0463, createdUser];
      this.persistUsersLikhesh24BCE0463(updated);
      return { likheshUsers_24BCE0463: updated };
    });

    return { success: true, message: `User "${createdUser.name}" created successfully.` };
  };

  updateUserRoleLikhesh24BCE0463 = (username, newRole) => {
    this.setState((prev) => {
      const updated = prev.likheshUsers_24BCE0463.map((u) =>
        u.username.toLowerCase() === username.toLowerCase() ? { ...u, role: newRole } : u
      );
      this.persistUsersLikhesh24BCE0463(updated);
      return { likheshUsers_24BCE0463: updated };
    });
    return { success: true, message: `Role updated to "${newRole}".` };
  };

  resetUserPasswordLikhesh24BCE0463 = (username, newPassword) => {
    this.setState((prev) => {
      const updated = prev.likheshUsers_24BCE0463.map((u) =>
        u.username.toLowerCase() === username.toLowerCase() ? { ...u, password: newPassword } : u
      );
      this.persistUsersLikhesh24BCE0463(updated);
      return { likheshUsers_24BCE0463: updated };
    });
    return { success: true, message: 'Password reset successfully.' };
  };

  deleteUserLikhesh24BCE0463 = (username) => {
    const current = this.state.likheshUser_24BCE0463;
    if (current && current.username.toLowerCase() === username.toLowerCase()) {
      return { success: false, message: 'Cannot delete the currently logged-in user.' };
    }

    this.setState((prev) => {
      const updated = prev.likheshUsers_24BCE0463.filter(
        (u) => u.username.toLowerCase() !== username.toLowerCase()
      );
      this.persistUsersLikhesh24BCE0463(updated);
      return { likheshUsers_24BCE0463: updated };
    });
    return { success: true, message: `User "${username}" removed.` };
  };

  render() {
    return (
      <AuthContext.Provider
        value={{
          user: this.state.likheshUser_24BCE0463,
          users: this.state.likheshUsers_24BCE0463,
          isBackendOnline: this.state.likheshBackendOnline_24BCE0463,
          login: this.loginLikhesh24BCE0463,
          logout: this.logoutLikhesh24BCE0463,
          checkBackendHealth: this.checkBackendHealthLikhesh24BCE0463,
          addUser: this.addUserLikhesh24BCE0463,
          updateUserRole: this.updateUserRoleLikhesh24BCE0463,
          resetUserPassword: this.resetUserPasswordLikhesh24BCE0463,
          deleteUser: this.deleteUserLikhesh24BCE0463,
        }}
      >
        {this.props.children}
      </AuthContext.Provider>
    );
  }
}

Likhesh24BCE0463AuthProvider.propTypes = { children: PropTypes.node.isRequired };
export default Likhesh24BCE0463AuthProvider;
