/* ===================================================================
   API Client Service — Likhesh | 24BCE0463
   Provides REST API methods to communicate with the PackTrack MySQL backend.
   Falls back to local operations if the backend server is unreachable.
   =================================================================== */

const API_BASE_URL =
  process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

console.log('[Likhesh | 24BCE0463] API Client initialized with base URL:', API_BASE_URL);

/**
 * Helper to get stored auth token
 */
const getAuthHeaders = () => {
  const token = localStorage.getItem('likhesh_token_24BCE0463');
  const headers = { 'Content-Type': 'application/json' };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  return headers;
};

export const api = {
  // -----------------------------------------------------------------
  // Health check to detect if MySQL backend is online
  // -----------------------------------------------------------------
  checkHealth: async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/health`, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
      });
      return res.ok;
    } catch (e) {
      return false;
    }
  },

  // -----------------------------------------------------------------
  // Auth endpoints
  // -----------------------------------------------------------------
  login: async (username, password) => {
    try {
      const res = await fetch(`${API_BASE_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password }),
      });
      const data = await res.json();
      return data;
    } catch (err) {
      console.warn('[Likhesh | 24BCE0463] Backend unreachable during login:', err.message);
      return { success: false, fallback: true, message: 'Backend not reachable.' };
    }
  },

  getCurrentUser: async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/auth/me`, {
        method: 'GET',
        headers: getAuthHeaders(),
      });
      return await res.json();
    } catch (err) {
      return { success: false, message: err.message };
    }
  },

  // -----------------------------------------------------------------
  // Package endpoints
  // -----------------------------------------------------------------
  getPackages: async (params = {}) => {
    try {
      const query = new URLSearchParams(params).toString();
      const url = `${API_BASE_URL}/packages${query ? `?${query}` : ''}`;
      const res = await fetch(url, {
        method: 'GET',
        headers: getAuthHeaders(),
      });
      return await res.json();
    } catch (err) {
      console.warn('[Likhesh | 24BCE0463] Error fetching packages from API:', err.message);
      return { success: false, fallback: true };
    }
  },

  getStats: async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/stats`, {
        method: 'GET',
        headers: getAuthHeaders(),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  submitPackage: async (packageData) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify(packageData),
      });
      return await res.json();
    } catch (err) {
      console.warn('[Likhesh | 24BCE0463] Error submitting package to API:', err.message);
      return { success: false, fallback: true };
    }
  },

  requestOtp: async (packageId) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/request-otp`, {
        method: 'PUT',
        headers: getAuthHeaders(),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  provideOtp: async (packageId, otp) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/provide-otp`, {
        method: 'PUT',
        headers: getAuthHeaders(),
        body: JSON.stringify({ otp }),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  receivePackage: async (packageId, otp, rackSlot) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/receive`, {
        method: 'PUT',
        headers: getAuthHeaders(),
        body: JSON.stringify({ otp, rackSlot }),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  collectPackage: async (packageId, otp) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/collect`, {
        method: 'PUT',
        headers: getAuthHeaders(),
        body: JSON.stringify({ otp }),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  requestReturn: async (packageId, reason) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/request-return`, {
        method: 'PUT',
        headers: getAuthHeaders(),
        body: JSON.stringify({ reason }),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  completeReturn: async (packageId) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/complete-return`, {
        method: 'PUT',
        headers: getAuthHeaders(),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  deletePackage: async (packageId) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}`, {
        method: 'DELETE',
        headers: getAuthHeaders(),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },

  overrideStatus: async (packageId, status, rackSlot) => {
    try {
      const res = await fetch(`${API_BASE_URL}/packages/${packageId}/override-status`, {
        method: 'PUT',
        headers: getAuthHeaders(),
        body: JSON.stringify({ status, rackSlot }),
      });
      return await res.json();
    } catch (err) {
      return { success: false, fallback: true };
    }
  },
};

export default api;
