import React, { Component } from 'react';
import './global.css';
import './App.css';
import Likhesh24BCE0463PackageProvider from './context/PackageContext';
import Likhesh24BCE0463AuthProvider from './context/AuthContext';
import Likhesh24BCE0463ThemeProvider from './context/ThemeContext';
import { AuthContext } from './context/AuthContext';
import Likhesh24BCE0463Navbar from './components/Navbar/Navbar';
import Likhesh24BCE0463Login from './components/Login/Login';
import Likhesh24BCE0463StudentSubmit from './components/StudentSubmit/StudentSubmit';
import Likhesh24BCE0463PeonPanel from './components/PeonPanel/PeonPanel';
import Likhesh24BCE0463TrackingDashboard from './components/TrackingDashboard/TrackingDashboard';
import Likhesh24BCE0463Portfolio from './components/Portfolio/Portfolio';
import Likhesh24BCE0463AdminPanel from './components/AdminPanel/AdminPanel';

/* ===================================================================
   App Component (Root) — Likhesh | 24BCE0463
   Main application shell with page routing for PackTrack system.
   Wraps everything in Theme + Auth + Package providers.
   Login-gated: user must authenticate before accessing any panel.
   Auto-resets active page when user role changes on login/logout.
   =================================================================== */

class Likhesh24BCE0463App extends Component {
  constructor(props) {
    super(props);

    this.state = {
      likheshActivePage_24BCE0463: 'submit',
    };

    // Track last logged-in username to detect user changes — Likhesh 24BCE0463
    this._lastUsernameLikhesh24BCE0463 = null;

    console.log('[Likhesh | 24BCE0463] App component initialized — PackTrack System');
  }

  // Get default landing page for a given role — Likhesh 24BCE0463
  getDefaultPageForRoleLikhesh24BCE0463 = (role) => {
    switch (role) {
      case 'student': return 'submit';
      case 'peon': return 'peon';
      case 'admin': return 'admin';
      default: return 'submit';
    }
  };

  // Method: navigate between pages — Likhesh 24BCE0463
  handleNavigateLikhesh24BCE0463 = (page) => {
    this.setState({ likheshActivePage_24BCE0463: page });
    console.log('[Likhesh | 24BCE0463] Navigated to:', page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Detect user change and reset page — Likhesh 24BCE0463
  handleUserChangeLikhesh24BCE0463 = (user) => {
    if (!user) {
      // User logged out — reset tracking
      if (this._lastUsernameLikhesh24BCE0463 !== null) {
        this._lastUsernameLikhesh24BCE0463 = null;
        // Reset to default on logout so next login starts fresh
        this.setState({ likheshActivePage_24BCE0463: 'submit' });
        console.log('[Likhesh | 24BCE0463] User logged out — page reset to default');
      }
      return;
    }

    // New user logged in (or first render with a session)
    if (this._lastUsernameLikhesh24BCE0463 !== user.username) {
      const defaultPage = this.getDefaultPageForRoleLikhesh24BCE0463(user.role);
      this._lastUsernameLikhesh24BCE0463 = user.username;
      // Only reset if we're on a page the user shouldn't see,
      // or if a different user just logged in
      this.setState({ likheshActivePage_24BCE0463: defaultPage });
      console.log('[Likhesh | 24BCE0463] User changed to:', user.username, '→ page:', defaultPage);
    }
  };

  render() {
    const { likheshActivePage_24BCE0463 } = this.state;

    return (
      <Likhesh24BCE0463ThemeProvider>
        <Likhesh24BCE0463AuthProvider>
          <Likhesh24BCE0463PackageProvider>
            <AuthContext.Consumer>
              {({ user }) => {
                // Detect user change and reset page — Likhesh 24BCE0463
                // Use setTimeout(0) to avoid setState-in-render warning
                if (!user && this._lastUsernameLikhesh24BCE0463 !== null) {
                  setTimeout(() => this.handleUserChangeLikhesh24BCE0463(null), 0);
                } else if (user && this._lastUsernameLikhesh24BCE0463 !== user.username) {
                  setTimeout(() => this.handleUserChangeLikhesh24BCE0463(user), 0);
                }

                return (
                  <>
                    {/* If not logged in, show Login screen */}
                    {!user ? (
                      <Likhesh24BCE0463Login />
                    ) : (
                      <div className="app" id="app-likhesh-24BCE0463">
                        {/* Navbar */}
                        <Likhesh24BCE0463Navbar
                          activePage={likheshActivePage_24BCE0463}
                          onNavigate={this.handleNavigateLikhesh24BCE0463}
                        />

                        {/* Main content */}
                        <main className="main">
                          {/* ===== Student Submit Page — Likhesh 24BCE0463 ===== */}
                          {likheshActivePage_24BCE0463 === 'submit' && (
                            <Likhesh24BCE0463StudentSubmit
                              onNavigate={this.handleNavigateLikhesh24BCE0463}
                            />
                          )}

                          {/* ===== Peon Gate Panel — Likhesh 24BCE0463 ===== */}
                          {likheshActivePage_24BCE0463 === 'peon' && (
                            <Likhesh24BCE0463PeonPanel
                              onNavigate={this.handleNavigateLikhesh24BCE0463}
                            />
                          )}

                          {/* ===== Tracking Dashboard — Likhesh 24BCE0463 ===== */}
                          {likheshActivePage_24BCE0463 === 'dashboard' && (
                            <Likhesh24BCE0463TrackingDashboard
                              onNavigate={this.handleNavigateLikhesh24BCE0463}
                            />
                          )}

                          {/* ===== Portfolio Page — Likhesh 24BCE0463 ===== */}
                          {likheshActivePage_24BCE0463 === 'portfolio' && (
                            <Likhesh24BCE0463Portfolio
                              onNavigate={this.handleNavigateLikhesh24BCE0463}
                            />
                          )}

                          {/* ===== Admin Master Control Panel — Likhesh 24BCE0463 ===== */}
                          {likheshActivePage_24BCE0463 === 'admin' && (
                            <Likhesh24BCE0463AdminPanel
                              onNavigate={this.handleNavigateLikhesh24BCE0463}
                            />
                          )}
                        </main>

                        {/* Footer — Likhesh 24BCE0463 */}
                        <footer className="footer">
                          <p>
                            Built with <span className="footerHeart">❤️</span> by{' '}
                            <strong>Likhesh — 24BCE0463</strong> | VIT Campus PackTrack
                            © 2026
                          </p>
                        </footer>
                      </div>
                    )}
                  </>
                );
              }}
            </AuthContext.Consumer>
          </Likhesh24BCE0463PackageProvider>
        </Likhesh24BCE0463AuthProvider>
      </Likhesh24BCE0463ThemeProvider>
    );
  }
}

export default Likhesh24BCE0463App;
