import React, { useContext } from 'react';
import PropTypes from 'prop-types';
import { PackageContext } from '../../context/PackageContext';
import { AuthContext } from '../../context/AuthContext';
import { ThemeContext } from '../../context/ThemeContext';
import styles from './Navbar.module.css';

/* ===================================================================
   Navbar Component — Likhesh | 24BCE0463
   Sticky navigation for PackTrack system.
   Includes theme toggle, user info, logout, and role-based nav items.
   =================================================================== */

function Likhesh24BCE0463Navbar({ activePage, onNavigate }) {
  const { getStats, isUsingDb } = useContext(PackageContext);
  const { user, logout, isBackendOnline } = useContext(AuthContext);
  const { theme, toggleTheme } = useContext(ThemeContext);

  const likheshStats_24BCE0463 = getStats();
  const dbConnected = isBackendOnline || isUsingDb;

  // Build nav items based on role — Likhesh 24BCE0463
  const likheshNavItems_24BCE0463 = [];

  if (user && user.role === 'admin') {
    likheshNavItems_24BCE0463.push({ key: 'admin', label: '🛡️ Admin Master Panel' });
  }
  if (user && (user.role === 'student' || user.role === 'admin')) {
    likheshNavItems_24BCE0463.push({ key: 'submit', label: '📦 Student Portal' });
  }
  if (user && (user.role === 'peon' || user.role === 'admin')) {
    likheshNavItems_24BCE0463.push({ key: 'peon', label: '🚪 Gate Panel' });
  }
  if (user) {
    likheshNavItems_24BCE0463.push({ key: 'dashboard', label: '📊 Dashboard' });
    likheshNavItems_24BCE0463.push({ key: 'portfolio', label: '🧑‍💻 Portfolio' });
  }

  console.log('[Likhesh | 24BCE0463] Navbar rendered — Active page:', activePage, 'Role:', user?.role);

  return (
    <nav className={styles.navbar} id="likhesh-navbar-24BCE0463">
      <div className={styles.navInner}>
        {/* Brand */}
        <div className={styles.brand}>
          <div className={styles.logoIcon}>📦</div>
          <div className={styles.brandText}>
            <span className={styles.brandName}>PackTrack</span>
            <span className={styles.brandSub}>VIT Campus Delivery System</span>
          </div>
        </div>

        {/* Right section */}
        <div className={styles.rightSection}>
          {/* Mini stats & DB status */}
          <div className={styles.miniStats}>
            <span
              className={styles.miniStat}
              title={dbConnected ? 'Connected to MySQL Database' : 'Running with local storage'}
              style={{ color: dbConnected ? '#69f0ae' : '#ffb74d', fontWeight: 600 }}
            >
              {dbConnected ? '🗄️ MySQL' : '💾 Local'}
            </span>
            <span className={styles.miniStatDivider}>|</span>
            <span className={styles.miniStat} title="Awaiting delivery">
              ⏳ {likheshStats_24BCE0463.pending}
            </span>
            <span className={styles.miniStatDivider}>|</span>
            <span className={styles.miniStat} title="In rack">
              📥 {likheshStats_24BCE0463.received}
            </span>
            <span className={styles.miniStatDivider}>|</span>
            <span className={styles.miniStat} title="Collected">
              ✅ {likheshStats_24BCE0463.collected}
            </span>
          </div>

          {/* Theme toggle */}
          <button
            className={styles.themeToggle}
            onClick={toggleTheme}
            title={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}
            id="theme-toggle-likhesh-24BCE0463"
          >
            {theme === 'light' ? '🌙' : '☀️'}
          </button>

          {/* User info + logout */}
          {user && (
            <div className={styles.userSection}>
              <span className={styles.userInfo}>
                <span className={styles.userRole}>
                  {user.role === 'student' ? '🎓' : user.role === 'peon' ? '🚪' : '🛡️'}
                </span>
                {user.name}
              </span>
              <button className={styles.logoutBtn} onClick={logout} id="logout-btn-likhesh-24BCE0463">
                🚪 Logout
              </button>
            </div>
          )}
        </div>

        {/* Nav links */}
        <div className={styles.navLinks}>
          {likheshNavItems_24BCE0463.map((item) => (
            <button
              key={item.key}
              id={`nav-${item.key}-likhesh-24BCE0463`}
              className={`${styles.navBtn} ${activePage === item.key ? styles.navBtnActive : ''}`}
              onClick={() => onNavigate(item.key)}
            >
              {item.label}
              {item.key === 'peon' && likheshStats_24BCE0463.pending > 0 && (
                <span className={styles.badge}>{likheshStats_24BCE0463.pending}</span>
              )}
            </button>
          ))}
        </div>
      </div>
    </nav>
  );
}

Likhesh24BCE0463Navbar.propTypes = {
  activePage: PropTypes.string.isRequired,
  onNavigate: PropTypes.func.isRequired,
};

export default Likhesh24BCE0463Navbar;
