import React, { Component } from 'react';
import PropTypes from 'prop-types';
import { PackageContext } from '../../context/PackageContext';
import styles from './TrackingDashboard.module.css';

/* ===================================================================
   TrackingDashboard Component — Likhesh | 24BCE0463
   Overview of all packages with real-time status, timeline, filters.
   Now includes return_requested and returned statuses.
   =================================================================== */

class Likhesh24BCE0463TrackingDashboard extends Component {
  static contextType = PackageContext;

  constructor(props) {
    super(props);
    this.state = {
      likheshSearchQuery_24BCE0463: '',
      likheshStatusFilter_24BCE0463: 'all',
    };
    console.log('[Likhesh | 24BCE0463] TrackingDashboard component initialized');
  }

  formatDateLikhesh24BCE0463 = (dateStr) => {
    if (!dateStr) return '—';
    const d = new Date(dateStr);
    return d.toLocaleDateString('en-IN', {
      day: 'numeric', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit',
    });
  };

  getProgressLikhesh24BCE0463 = (status) => {
    switch (status) {
      case 'pending': return 20;
      case 'received': return 50;
      case 'collected': return 75;
      case 'return_requested': return 90;
      case 'returned': return 100;
      default: return 0;
    }
  };

  getStatusLabelLikhesh24BCE0463 = (status) => {
    switch (status) {
      case 'pending': return { text: '⏳ Awaiting Delivery', color: '#ff9100' };
      case 'received': return { text: '📥 In Rack — Ready', color: '#00c853' };
      case 'collected': return { text: '✅ Collected', color: '#9c27b0' };
      case 'return_requested': return { text: '↩️ Return Requested', color: '#f57c00' };
      case 'returned': return { text: '🔄 Returned', color: '#1565c0' };
      default: return { text: 'Unknown', color: '#999' };
    }
  };

  render() {
    const { packages, searchPackages, getStats } = this.context;
    const { likheshSearchQuery_24BCE0463, likheshStatusFilter_24BCE0463 } = this.state;

    const likheshStats_24BCE0463 = getStats();

    let likheshFiltered_24BCE0463 = likheshSearchQuery_24BCE0463
      ? searchPackages(likheshSearchQuery_24BCE0463)
      : packages;

    if (likheshStatusFilter_24BCE0463 !== 'all') {
      likheshFiltered_24BCE0463 = likheshFiltered_24BCE0463.filter(
        (p) => p.status === likheshStatusFilter_24BCE0463
      );
    }

    return (
      <div className={styles.dashboardPage} id="tracking-dashboard-likhesh-24BCE0463">
        <div className={styles.container}>
          <div className={styles.header}>
            <div className={styles.headerIcon}>📊</div>
            <h1 className={styles.headerTitle}>Package Tracking Dashboard</h1>
            <p className={styles.headerSubtitle}>Real-time overview of all campus deliveries</p>
          </div>

          {/* Stats */}
          <div className={styles.statsGrid}>
            {[
              { key: 'all', icon: '📦', val: likheshStats_24BCE0463.total, label: 'Total', cls: styles.statTotal },
              { key: 'pending', icon: '⏳', val: likheshStats_24BCE0463.pending, label: 'Awaiting', cls: styles.statPending },
              { key: 'received', icon: '📥', val: likheshStats_24BCE0463.received, label: 'In Rack', cls: styles.statReceived },
              { key: 'collected', icon: '✅', val: likheshStats_24BCE0463.collected, label: 'Collected', cls: styles.statCollected },
              { key: 'return_requested', icon: '↩️', val: likheshStats_24BCE0463.returnRequested, label: 'Returns', cls: styles.statReturn },
              { key: 'returned', icon: '🔄', val: likheshStats_24BCE0463.returned, label: 'Returned', cls: styles.statReturned },
            ].map((s) => (
              <div key={s.key}
                className={`${styles.statCard} ${s.cls} ${likheshStatusFilter_24BCE0463 === s.key ? styles.statActive : ''}`}
                onClick={() => this.setState({ likheshStatusFilter_24BCE0463: s.key })}
              >
                <div className={styles.statIconWrap}>{s.icon}</div>
                <div className={styles.statInfo}>
                  <div className={styles.statValue}>{s.val}</div>
                  <div className={styles.statLabel}>{s.label}</div>
                </div>
              </div>
            ))}
          </div>

          {/* Search */}
          <div className={styles.searchBar}>
            <span className={styles.searchIcon}>🔍</span>
            <input className={styles.searchInput} type="text"
              placeholder="Search by Tracking ID, Reg No, Name, or Company..."
              value={likheshSearchQuery_24BCE0463}
              onChange={(e) => this.setState({ likheshSearchQuery_24BCE0463: e.target.value })}
            />
            {likheshSearchQuery_24BCE0463 && (
              <button className={styles.clearSearch}
                onClick={() => this.setState({ likheshSearchQuery_24BCE0463: '' })}>✕</button>
            )}
          </div>

          <div className={styles.resultCount}>
            Showing <strong>{likheshFiltered_24BCE0463.length}</strong> package{likheshFiltered_24BCE0463.length !== 1 ? 's' : ''}
            {likheshStatusFilter_24BCE0463 !== 'all' && (
              <span className={styles.filterTag}>
                {likheshStatusFilter_24BCE0463.replace('_', ' ')}
                <button className={styles.filterClear}
                  onClick={() => this.setState({ likheshStatusFilter_24BCE0463: 'all' })}>✕</button>
              </span>
            )}
          </div>

          {likheshFiltered_24BCE0463.length === 0 ? (
            <div className={styles.emptyState}>
              <div className={styles.emptyIcon}>📭</div>
              <p className={styles.emptyText}>No packages found.</p>
              <p className={styles.emptyHint}>Submit a package to get started!</p>
            </div>
          ) : (
            <div className={styles.packageGrid}>
              {likheshFiltered_24BCE0463.map((pkg) => {
                const likheshSI_24BCE0463 = this.getStatusLabelLikhesh24BCE0463(pkg.status);
                const likheshProg_24BCE0463 = this.getProgressLikhesh24BCE0463(pkg.status);

                return (
                  <div className={styles.trackingCard} key={pkg.id}>
                    <div className={styles.cardHeader}>
                      <div className={styles.cardCompany}>
                        <span className={styles.cardCompanyIcon}>
                          {pkg.company === 'Amazon' ? '📦' : pkg.company === 'Flipkart' ? '🛒' : '🏷️'}
                        </span>
                        {pkg.company}
                      </div>
                      <span className={styles.cardStatus}
                        style={{ background: likheshSI_24BCE0463.color + '18', color: likheshSI_24BCE0463.color }}>
                        {likheshSI_24BCE0463.text}
                      </span>
                    </div>

                    <div className={styles.progressBar}>
                      <div className={styles.progressFill}
                        style={{ width: `${likheshProg_24BCE0463}%`, background: likheshSI_24BCE0463.color }}></div>
                    </div>

                    <div className={styles.cardBody}>
                      <div className={styles.cardRow}>
                        <span className={styles.cardLabel}>Student</span>
                        <span className={styles.cardValue}>{pkg.studentName}</span>
                      </div>
                      <div className={styles.cardRow}>
                        <span className={styles.cardLabel}>Reg No</span>
                        <span className={styles.cardValue}>{pkg.regNumber}</span>
                      </div>
                      <div className={styles.cardRow}>
                        <span className={styles.cardLabel}>Tracking</span>
                        <span className={`${styles.cardValue} ${styles.trackingId}`}>{pkg.trackingId}</span>
                      </div>
                      <div className={styles.cardRow}>
                        <span className={styles.cardLabel}>OTP Mode</span>
                        <span className={styles.cardValue}>
                          {pkg.otpMode === 'upfront' ? '🔑 Upfront' : '📲 On Arrival'}
                        </span>
                      </div>
                      {pkg.rackSlot && (
                        <div className={styles.cardRow}>
                          <span className={styles.cardLabel}>Rack</span>
                          <span className={styles.rackBadge}>{pkg.rackSlot}</span>
                        </div>
                      )}
                      {pkg.returnReason && (
                        <div className={styles.cardRow}>
                          <span className={styles.cardLabel}>Return</span>
                          <span className={styles.cardValue}>{pkg.returnReason}</span>
                        </div>
                      )}
                    </div>

                    {/* Timeline */}
                    <div className={styles.timeline}>
                      <div className={`${styles.timelineStep} ${styles.timelineComplete}`}>
                        <div className={styles.timelineDot}></div>
                        <div className={styles.timelineInfo}>
                          <span className={styles.timelineLabel}>Submitted</span>
                          <span className={styles.timelineDate}>{this.formatDateLikhesh24BCE0463(pkg.createdAt)}</span>
                        </div>
                      </div>
                      <div className={`${styles.timelineStep} ${pkg.status !== 'pending' ? styles.timelineComplete : ''}`}>
                        <div className={styles.timelineDot}></div>
                        <div className={styles.timelineInfo}>
                          <span className={styles.timelineLabel}>Received</span>
                          <span className={styles.timelineDate}>{this.formatDateLikhesh24BCE0463(pkg.receivedAt)}</span>
                        </div>
                      </div>
                      <div className={`${styles.timelineStep} ${['collected', 'return_requested', 'returned'].includes(pkg.status) ? styles.timelineComplete : ''}`}>
                        <div className={styles.timelineDot}></div>
                        <div className={styles.timelineInfo}>
                          <span className={styles.timelineLabel}>Collected</span>
                          <span className={styles.timelineDate}>{this.formatDateLikhesh24BCE0463(pkg.collectedAt)}</span>
                        </div>
                      </div>
                      {(pkg.status === 'return_requested' || pkg.status === 'returned') && (
                        <div className={`${styles.timelineStep} ${pkg.status === 'returned' ? styles.timelineComplete : ''}`}>
                          <div className={styles.timelineDot}></div>
                          <div className={styles.timelineInfo}>
                            <span className={styles.timelineLabel}>
                              {pkg.status === 'returned' ? 'Returned' : 'Return Pending'}
                            </span>
                            <span className={styles.timelineDate}>
                              {this.formatDateLikhesh24BCE0463(pkg.returnCompletedAt || pkg.returnRequestedAt)}
                            </span>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    );
  }
}

Likhesh24BCE0463TrackingDashboard.propTypes = { onNavigate: PropTypes.func.isRequired };
export default Likhesh24BCE0463TrackingDashboard;
